function acceptGovernance() external {
        if (msg.sender != pendingGovernance || msg.sender == address(0) ||
            canonicalState != 0 || preparationActive) revert Unauthorized();
        address previous=governance;governance=msg.sender;pendingGovernance=address(0);
        emit GovernanceAccepted(previous,msg.sender);
    }

function bind(bytes32 id, address implementation) external {
        if (msg.sender != bootstrap || isSealed) revert Unauthorized();
        bytes32[16] memory supported=_moduleIds();bool known;
        for(uint256 i;i<supported.length;++i)if(id==supported[i]){known=true;break;}
        if(!known)revert InvalidConfiguration();
        if (implementation.code.length == 0 || module[id] != address(0) ||
            address(IZZZBound(implementation).access()) != address(this)) revert InvalidConfiguration();
        module[id] = implementation;
        emit ModuleBound(id, implementation);
    }

function bindProtocolPolicy(address implementation) external {
        if (msg.sender != bootstrap || isSealed) revert Unauthorized();
        if (protocolPolicy != address(0) || implementation.code.length == 0 ||
            IZZZProtocolPolicy(implementation).access() != address(this) ||
            IZZZProtocolPolicy(implementation).PROTOCOL_POLICY_VERSION() != 1) revert InvalidConfiguration();
        protocolPolicy = implementation;
        emit ProtocolPolicyBound(implementation, implementation.codehash);
    }

function cancelPreparation(bytes32 noticeHash) external {
        if (msg.sender != governance || !preparationActive || canonicalState != 0) revert Unauthorized();
        if (noticeHash != preparationHash) revert InvalidConfiguration();
        preparationActive = false;
        emit PreparationCancelled(noticeHash);
    }

function canonicalTransition(uint8 state, bool settling, bool clearPreparation) external {
        if (lpExitStarted || msg.sender != canonicalHandoff() || msg.sender == address(0) || state > 4 || (settling && state != 1)) revert Unauthorized();
        // States 3/4 are terminal; any impossible higher state also fails closed.
        if (canonicalState > 2) revert InvalidConfiguration();
        canonicalState = state;
        canonicalSettling = settling;
        if (clearPreparation) preparationActive = false;
    }

function proposeGovernance(address candidate) external {
        if (msg.sender != governance || canonicalState != 0 || preparationActive) revert Unauthorized();
        if (candidate == address(this) || candidate == governance) revert InvalidConfiguration();
        pendingGovernance = candidate;
        emit GovernanceProposed(governance,candidate);
    }

function seal() external {
        if (msg.sender != bootstrap || isSealed) revert Unauthorized();
        if (protocolPolicy.code.length == 0 ||
            IZZZProtocolPolicy(protocolPolicy).access() != address(this) ||
            IZZZProtocolPolicy(protocolPolicy).PROTOCOL_POLICY_VERSION() != 1) revert InvalidConfiguration();
        bytes32[16] memory required = _moduleIds();
        for (uint256 i; i < required.length; ++i) {
            if (module[required[i]].code.length == 0 || module[required[i]] == protocolPolicy) revert InvalidConfiguration();
            for (uint256 j; j < i; ++j) {
                if (module[required[i]] == module[required[j]]) revert InvalidConfiguration();
            }
        }
        if (ICanonicalOwnerBinding(module[Ids.NFT_CANONICAL]).nft() != module[Ids.NFT] ||
            ICanonicalOwnerBinding(module[Ids.VAULT_CANONICAL]).vault() != module[Ids.VAULT] ||
            ICanonicalOwnerBinding(module[Ids.FEES_CANONICAL]).fees() != module[Ids.FEES]) revert InvalidConfiguration();

        // The source identity is bootstrap-only. Never seal an unset token and
        // leave a deployment unable to accept its intended ZZZ contributions.
        address sourceZZZ = IContributionRegistry(module[Ids.POOLS]).activationAssets().zzz();
        if (sourceZZZ == address(0) || IExitIdentity(module[Ids.MIGRATION]).currentZZZ() != sourceZZZ) revert InvalidConfiguration();
        IZZZProtocolPolicy(protocolPolicy).validateMintRecipient();

        // NFT randomness is configured only before sealing. Do not irreversibly
        // lock the canonical collection while its mint configuration is absent.
        if (IZZZVault(module[Ids.VAULT]).canonicalChainId() == block.chainid &&
            !IZZZNFT(module[Ids.NFT]).randomnessConfigured()) revert InvalidConfiguration();
        isSealed = true;
        bootstrap = address(0);
        emit SystemSealed();
    }

function setGuardian(address who, bool enabled) external {
        if (!canConfigure(msg.sender) || who == address(0)) revert Unauthorized();
        guardians[who] = enabled;
        emit GuardianChanged(who, enabled);
    }

function setKeeper(address who, bool enabled) external {
        if (!canConfigure(msg.sender) || who == address(0)) revert Unauthorized();
        keepers[who] = enabled;
        emit KeeperChanged(who, enabled);
    }

function setPaused(bool state) external {
        // Pause control remains available to drain incoming custody and park it.
        // Unpausing never bypasses the separate preparation guards.
        if (msg.sender != governance && !(!isSealed && msg.sender == bootstrap) &&
            !(state && guardians[msg.sender])) revert Unauthorized();
        paused = state;
        emit PauseChanged(state);
    }

function startLPExit() external {
        if (msg.sender != module[Ids.VAULT] || !isSealed || !paused || lpExitStarted ||
            preparationActive || canonicalState != 0) revert Unauthorized();
        lpExitStarted = true;
        emit LPExitStarted();
    }

function startPreparation(PreparationNotice calldata notice) external {
        if (msg.sender != governance || !isSealed || preparationActive || lpExitStarted || canonicalState != 0) revert Unauthorized();
        if (IZZZVault(module[Ids.VAULT]).canonicalChainId() != block.chainid ||
            notice.destinationChain != block.chainid || notice.successorController == address(0) ||
            (notice.destinationChain == block.chainid && notice.successorController == address(this)) ||
            notice.deploymentCommitment == bytes32(0) || notice.reviewHash == bytes32(0)) revert InvalidConfiguration();
        preparationReadyDestination = false;
        if (notice.destinationChain == block.chainid && notice.successorController.code.length != 0) {
            IZZZAccess destination = IZZZAccess(notice.successorController);
            // Freeze cannot authenticate a configuration that bootstrap changed
            // after the notice was reviewed. A usable local importer is already
            // sealed, inert and bound to this source when announcement executes.
            if (!destination.isSealed() || destination.canonicalState() != 2) revert InvalidConfiguration();
            ZZZCanonicalHandoff handoff = ZZZCanonicalHandoff(destination.canonicalHandoff());
            if (handoff.incomingSource() != address(this) ||
                handoff.deploymentCommitment() != notice.deploymentCommitment) revert InvalidConfiguration();
            preparationReadyDestination = true;
        }
        uint256 nonce = ++preparationNonce;
        bytes32 noticeHash = keccak256(abi.encode("ZZZ_CANONICAL_PREPARATION_V1", block.chainid, address(this),
            module[Ids.VAULT], module[Ids.NFT], nonce, notice));
        preparationNotice = notice;
        preparationHash = noticeHash;
        preparationStartedAt = block.timestamp;
        preparationActive = true;
        emit PreparationStarted(noticeHash, nonce, notice.destinationChain, notice.successorController,
            notice.deploymentCommitment, notice.reviewHash);
    }

function admitPoolAsset(address token) external returns (bytes32 id) {
        if (msg.sender != registry) revert Unauthorized();
        id = activePolicy[token];
        if (id != bytes32(0)) return id;
        bytes32 codeHash = token == address(0) ? NATIVE_ASSET_CODE_HASH : token.codehash;
        uint8 decimals = _validate(token, codeHash);
        // This binds the authenticated pool-configuration admission, not an
        // independent audit. Explicit reviews use governance's supplied hash.
        bytes32 admissionReference = keccak256(abi.encode("ZZZ_POOL_ASSET_ADMISSION_V1", registry, token, codeHash, decimals));
        // A target pair may use another accounting currency (for example WETH).
        // Pool admission must not make that currency an externally supplied asset.
        return _record(Policy(token, isContributionAsset(token), codeHash, admissionReference, decimals, true));
    }

function configureZZZ(address token, bytes32 expectedCodeHash, bytes32 reviewHash)
        external onlyGovernance returns (bytes32 id) {
        if (zzz != address(0) || access.isSealed() || token == address(0) || reviewHash == bytes32(0)) revert InvalidConfiguration();
        uint8 decimals = _validate(token, expectedCodeHash);
        zzz = token;
        id = _record(Policy(token, true, expectedCodeHash, reviewHash, decimals, false));
        emit ZZZIdentityConfigured(token, expectedCodeHash, reviewHash);
    }

function setAsset(address token, bool enabled, bytes32 expectedCodeHash, bytes32 reviewHash)
        external onlyGovernance returns (bytes32 id) {
        if (reviewHash == bytes32(0)) revert InvalidConfiguration();
        bytes32 previous = activePolicy[token];
        uint8 decimals = previous == bytes32(0) ? 0 : policies[previous].decimals;
        if (enabled) {
            if (!isContributionAsset(token)) revert InvalidConfiguration();
            decimals = _validate(token, expectedCodeHash);
        }
        return _record(Policy(token, enabled, expectedCodeHash, reviewHash, decimals, false));
    }

function create() external returns(address child) {
        if (assetsOf[msg.sender]!=address(0)) revert AlreadyCreated();
        child=address(new ZZZActivationAssets(access,msg.sender));
        assetsOf[msg.sender]=child;
    }

function executeReviewed(Request calldata request, uint16 maximumLossBps,bytes32 expectedContributionPolicy)
        external payable live operating principalOperating nonReentrant {
        _deadline(request.deadline);
        IZZZProtocolPolicy policySource=IZZZProtocolPolicy(access.protocolPolicy());
        if(expectedContributionPolicy==bytes32(0) || policySource.entryFingerprint()!=expectedContributionPolicy)
            revert InvalidState();
        IZZZProtocolPolicy.EntryPolicy memory entryTerms=policySource.entryPolicy();
        address vault = _vault();
        if (request.amountIn == 0 || request.minimumLiquidity == 0 || _owner(request.nftId) != msg.sender) revert Unauthorized();
        PoolConfig memory pool = IZZZPools(registry).accounting(request.poolId);
        if (!pool.depositsEnabled || !pool.operationsEnabled ||
            pool.key.currency0 == pool.key.currency1) revert InvalidConfiguration();
        address source = request.sourceAsset;
        if (!activationAssets.isContributionAsset(source)) revert InvalidConfiguration();
        if (source != pool.key.currency0 && source != pool.key.currency1) revert InvalidConfiguration();
        if (msg.value != (source == address(0) ? request.amountIn : 0)) revert InvalidAmount();
        uint256 nativeBaseline = address(this).balance - msg.value;
        uint256 sourceBaseline = ExactAsset.balance(source,address(this)) - (source == address(0) ? msg.value : 0);
        // Freeze source + LP-pair prices BEFORE token pulls or approvals can
        // call external code. Both bounds come from two sources.
        uint256 grossUSD = activationAssets.value(source, request.amountIn);
        if (grossUSD == 0 || grossUSD < (request.increase?entryTerms.minGrowthUSD:entryTerms.minActivationUSD))
            revert InvalidAmount();
        if (_pricing().beginEntryReviewed(request.nftId,request.poolId,source,request.amountIn,maximumLossBps,
            expectedContributionPolicy) != grossUSD) revert InvalidState();
        if (source != address(0)) ExactToken.pull(source, msg.sender, request.amountIn);
        if (_owner(request.nftId) != msg.sender) revert Unauthorized();
        uint256 amount0 = source == pool.key.currency0 ? request.amountIn : 0;
        uint256 amount1 = source == pool.key.currency1 ? request.amountIn : 0;
        bytes memory payload = request.increase
            ? abi.encodeCall(IActivationVault.increase, (request.nftId, amount0, amount1, request.minimumLiquidity, request.deadline))
            : abi.encodeCall(IActivationVault.activate, (request.nftId, request.poolId, amount0, amount1, request.minimumLiquidity, request.deadline));
        // Token approval can call arbitrary token code. Context must remain
        // inactive until the immediate Vault call, whose own guard then protects
        // contribution valuation against unrelated callback-driven joins.
        ExactAsset.approve(source,vault, request.amountIn);
        if (_owner(request.nftId) != msg.sender) revert Unauthorized();
        context = Context(msg.sender, request.nftId, keccak256(payload), request.poolId, amount0, amount1, grossUSD);
        (bool success, bytes memory result) = vault.call{value: source == address(0) ? request.amountIn : 0}(payload);
        if (!success) assembly ("memory-safe") { revert(add(result, 32), mload(result)) }
        delete context;
        ExactAsset.approve(source,vault, 0);
        if (_owner(request.nftId) != msg.sender || ExactAsset.balance(source,address(this)) != sourceBaseline || address(this).balance != nativeBaseline) revert InvalidState();
        _pricing().endEntry();
        if(policySource.entryFingerprint()!=expectedContributionPolicy)revert InvalidState();
        emit SourceContributed(msg.sender, request.nftId, request.poolId, request.sourceAsset,
            request.amountIn, grossUSD, source, request.amountIn, request.increase);
    }

function execute(address token, uint256 amount, bytes32 poolId, uint256 deadline) external onlyKeeper live operating nonReentrant {
        _deadline(deadline);
        if (amount == 0 || operatingTradeUSD == 0) revert InvalidAmount();
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        // The maximum spend must hold at either admitted source price. Ordinary
        // Oracle.value is the lower mark for minimum contributions/display; it
        // can understate a trade budget. Round the upper input value upward.
        (, uint256 upper,) = oracle.priceBounds(token);
        if (Math.mulDiv(amount, upper, 10 ** oracle.tokenDecimals(token), Math.Rounding.Ceil) > operatingTradeUSD)
            revert InvalidAmount();
        uint256 beforeZZZ = IERC20(zzz).balanceOf(address(this));
        uint256 beforeInput = ExactAsset.balance(token,address(this));
        IZZZFees(access.module(Ids.FEES)).releaseBuyback(token, amount);
        if (ExactAsset.balance(token,address(this)) != beforeInput + amount) revert InvalidState();
        uint256 acquired = amount;
        if (token != zzz) {
            PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
            bool zeroForOne = c.key.currency0 == token && c.key.currency1 == zzz;
            if (!zeroForOne && !(c.key.currency1 == token && c.key.currency0 == zzz)) revert InvalidConfiguration();
            uint256 minimum = Math.mulDiv(oracle.quote(token, zzz, amount), 10000 - c.maxSlippageBps, 10000);
            address manager = access.module(Ids.LIQUIDITY);
            ExactAsset.approve(token,manager, amount);
            acquired = IZZZLiquidity(manager).swap{value: token == address(0) ? amount : 0}(poolId, zeroForOne, amount, minimum, deadline);
            ExactAsset.approve(token,manager, 0);
            if (ExactAsset.balance(token,address(this)) != beforeInput) revert InvalidState();
        }
        if (IERC20(zzz).balanceOf(address(this)) != beforeZZZ + acquired) revert InvalidState();
        uint256 supplyBefore = IBurnable(zzz).totalSupply();
        IBurnable(zzz).burn(acquired);
        if (IBurnable(zzz).totalSupply() + acquired != supplyBefore ||
            IERC20(zzz).balanceOf(address(this)) != beforeZZZ) revert InvalidState();
        emit BoughtAndBurned(token, amount, acquired);
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }

function setMaximumTradeUSD(uint256 limit,bytes32 reviewHash) external onlyGovernance operating nonReentrant {
        if(limit == 0 || limit > type(uint128).max || limit < operatingTradeUSD || reviewHash == bytes32(0))
            revert InvalidConfiguration();
        emit MaximumTradeLimitChanged(maxTradeUSD,limit,reviewHash);
        maxTradeUSD = limit;
    }

function setOperatingTradeUSD(uint256 limit) external onlyGovernance operating nonReentrant {
        if (limit > maxTradeUSD) revert InvalidConfiguration();
        uint256 previous = operatingTradeUSD;
        operatingTradeUSD = limit;
        emit OperatingTradeLimitChanged(previous, limit);
    }

function abort() external governance nonReentrant {
        if (phase != PHASE_EXPORTING && phase != PHASE_SETTLING) revert InvalidState();
        phase = PHASE_ABORTING;
        _peer(destinationController).cancelImport();
        emit AbortStarted(handoffId);
    }

function acceptFunding(uint8 slot, uint256 index) external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_IMPORTED_AWAITING_BACKING || slot >= SLOTS
                || index >= assetCount[slot] || incomingFunded[slot][index] || !source.funded(slot, index)
        ) revert Unauthorized();
        incomingFunded[slot][index] = true;
        _module(slot).canonicalAccept(index, source.moduleAt(slot));
    }

function activate() external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_IMPORTED_AWAITING_BACKING || source.phase() != PHASE_RETIRED
                || source.destinationController() != address(access) || source.stateRoot() != stateRoot
        ) {
            revert Unauthorized();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (!incomingFunded[slot][index]) revert InvalidBacking();
            }
            _module(slot).canonicalValidate();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            _module(slot).canonicalActivate();
        }
        phase = PHASE_ACTIVE_REPLACEMENT;
        access.canonicalTransition(STATE_OPERATING, false, true);
        emit Activated(handoffId, incomingSource, stateRoot);
    }

function bindFrozen(bytes32 id) external {
        if (phase != PHASE_IMPORTING || msg.sender != address(_peer(incomingSource)) || handoffId != bytes32(0)) {
            revert Unauthorized();
        }
        handoffId = id;
        ZZZCanonicalHandoff source = ZZZCanonicalHandoff(msg.sender);
        if (source.handoffId() != id || source.destinationController() != address(access)) revert InvalidState();
        for (uint8 slot; slot < SLOTS; ++slot) {
            recordCount[slot] = source.recordCount(slot);
            assetCount[slot] = source.assetCount(slot);
        }
    }

function cancelImport() external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || source.phase() != PHASE_ABORTING
                || (phase != PHASE_IMPORTING && phase != PHASE_IMPORTED_AWAITING_BACKING)
        ) {
            revert Unauthorized();
        }
        phase = PHASE_CANCELLED_IMPORT;
        access.canonicalTransition(STATE_CANCELLED, false, false);
    }

function commit() external governance nonReentrant {
        if (phase != PHASE_EXPORTING || stateRoot == bytes32(0)) revert InvalidState();
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (
            peer.phase() != PHASE_IMPORTED_AWAITING_BACKING || peer.stateRoot() != stateRoot
                || peer.deploymentCommitment() != destinationDeployment
        ) revert InvalidState();
        _allFunded();
        // Both transitions are atomic on this chain. A failed readiness or
        // backing check rolls retirement back; no competing successor is added.
        phase = PHASE_RETIRED;
        access.canonicalTransition(STATE_RETIRED, false, false);
        ICanonicalHelpers(access.module(Ids.NFT)).canonicalRetire();
        peer.activate();
        emit Retired(handoffId, destinationController, stateRoot);
    }

function completeImport() external nonReentrant {
        if (phase != PHASE_IMPORTING) revert InvalidState();
        ZZZCanonicalHandoff source = _peer(incomingSource);
        for (uint8 slot; slot < SLOTS; ++slot) {
            if (
                importCursor[slot] != recordCount[slot] || importRoot[slot] != source.exportRoot(slot)
                    || _module(slot).canonicalCount() != recordCount[slot]
                    || _module(slot).canonicalAssetCount() != assetCount[slot]
            ) revert InvalidRecord();
        }
        stateRoot = keccak256(abi.encode(handoffId, recordCount, assetCount, importRoot));
        if (source.phase() != PHASE_EXPORTING || stateRoot == bytes32(0) || stateRoot != source.stateRoot()) {
            revert InvalidRecord();
        }
        importComplete = true;
        phase = PHASE_IMPORTED_AWAITING_BACKING;
    }

function exportRows(uint8 slot, uint256 count) external nonReentrant {
        if (
            phase != PHASE_EXPORTING || slot >= SLOTS || count == 0 || count > MAX_ROWS
                || exportCursor[slot] + count > recordCount[slot]
        ) revert InvalidState();
        uint256 end = exportCursor[slot] + count;
        for (uint256 row = exportCursor[slot]; row < end; ++row) {
            bytes memory record = _module(slot).canonicalExport(row);
            exportRoot[slot] = _next(exportRoot[slot], slot, row, record);
            emit RecordExported(handoffId, slot, row, record);
        }
        exportCursor[slot] = end;
        bool complete = true;
        for (uint8 i; i < SLOTS; ++i) {
            if (exportCursor[i] != recordCount[i]) complete = false;
        }
        if (complete) {
            stateRoot = keccak256(abi.encode(handoffId, recordCount, assetCount, exportRoot));
            emit SnapshotCommitted(handoffId, stateRoot);
        }
    }

function finishAbort() external governance nonReentrant {
        if (phase != PHASE_ABORTING || _peer(destinationController).phase() != PHASE_CANCELLED_IMPORT) {
            revert InvalidState();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (funded[slot][index] && !returned[slot][index]) revert InvalidBacking();
            }
            _module(slot).canonicalValidate();
        }
        phase = incomingSource == address(0) ? PHASE_IDLE : PHASE_ACTIVE_REPLACEMENT;
        access.canonicalTransition(STATE_OPERATING, false, true);
        emit Aborted(handoffId);
    }

function freeze() external governance nonReentrant {
        if (
            access.lpExitStarted() || (phase != PHASE_IDLE && phase != PHASE_ACTIVE_REPLACEMENT) || !access.preparationActive()
                || access.canonicalState() != STATE_OPERATING || !access.preparationReadyDestination()
        ) {
            revert InvalidState();
        }
        (uint256 chain, address destination, bytes32 deployment,) = access.preparationNotice();
        if (chain != block.chainid) revert UnsupportedTransport();
        ZZZCanonicalHandoff peer = _peer(destination);
        if (
            !IZZZAccess(destination).isSealed() || peer.SCHEMA() != SCHEMA || peer.phase() != PHASE_IMPORTING
                || peer.incomingSource() != address(access) || peer.deploymentCommitment() != deployment
        ) {
            revert InvalidState();
        }
        if (IZZZVault(IZZZAccess(destination).module(Ids.VAULT)).canonicalChainId() != block.chainid) {
            revert UnsupportedTransport();
        }
        // Every bucket must be parked and have no active custody handoff.
        // Capture enforces that boundary; no retired v3 channel is admitted.
        destinationController = destination;
        destinationDeployment = deployment;
        handoffId = keccak256(
            abi.encode(
                SCHEMA,
                block.chainid,
                address(access),
                address(this),
                destination,
                address(peer),
                access.preparationHash(),
                deployment
            )
        );
        phase = PHASE_SETTLING;
        settlementCursor = 0;
        stateRoot = bytes32(0);
        // Establish the guard BEFORE any external balance observation. Capture
        // every module first, then process only those immutable cutoffs.
        access.canonicalTransition(STATE_FROZEN, false, false);
        for (uint8 slot; slot < SLOTS; ++slot) {
            _module(slot).canonicalCapture();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            recordCount[slot] = _module(slot).canonicalCount();
            assetCount[slot] = _module(slot).canonicalAssetCount();
            if (recordCount[slot] == 0 || assetCount[slot] > 256) {
                revert InvalidState();
            }
            exportCursor[slot] = 0;
            exportRoot[slot] = bytes32(0);
            for (uint256 index; index < assetCount[slot]; ++index) {
                funded[slot][index] = false;
                returned[slot][index] = false;
            }
        }
        peer.bindFrozen(handoffId);
        emit Frozen(handoffId, destination);
    }

function fund(uint8 slot, uint256 index) external nonReentrant {
        if (phase != PHASE_EXPORTING || slot >= SLOTS || index >= assetCount[slot] || funded[slot][index]) {
            revert InvalidState();
        }
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (peer.phase() != PHASE_IMPORTED_AWAITING_BACKING || peer.stateRoot() != stateRoot || stateRoot == bytes32(0))
        revert InvalidState();
        (address asset, uint256 amount) = _module(slot).canonicalBacking(index);
        IZZZCanonicalModule destination = IZZZCanonicalModule(peer.moduleAt(slot));
        (address otherAsset, uint256 otherAmount) = destination.canonicalBacking(index);
        if (otherAsset != asset || otherAmount != amount) revert InvalidBacking();
        funded[slot][index] = true;
        uint256 beforeBalance = _balance(asset, address(destination));
        _module(slot).canonicalRelease(index, address(destination));
        if (_balance(asset, address(destination)) != beforeBalance + amount) revert InvalidBacking();
        peer.acceptFunding(slot, index);
        emit BackingTransferred(handoffId, slot, index, asset, amount);
    }

function importRows(uint8 slot, bytes[] calldata records) external nonReentrant {
        if (
            phase != PHASE_IMPORTING || slot >= SLOTS || records.length == 0 || records.length > MAX_ROWS
                || importCursor[slot] + records.length > recordCount[slot]
        ) revert InvalidState();
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (source.phase() != PHASE_EXPORTING || source.stateRoot() == bytes32(0) || source.handoffId() != handoffId) {
            revert InvalidState();
        }
        IZZZCanonicalModule sourceModule = IZZZCanonicalModule(source.moduleAt(slot));
        for (uint256 i; i < records.length; ++i) {
            uint256 row = importCursor[slot]++;
            if (keccak256(records[i]) != keccak256(sourceModule.canonicalExport(row))) revert InvalidRecord();
            _module(slot).canonicalImport(row, records[i]);
            importRoot[slot] = _next(importRoot[slot], slot, row, records[i]);
            emit RecordImported(handoffId, slot, row);
        }
    }

function prepareImport(address sourceController) external nonReentrant {
        if (
            access.isSealed() || msg.sender != access.bootstrap() || phase != PHASE_IDLE
                || sourceController == address(access) || sourceController.code.length == 0
                || !IZZZAccess(sourceController).isSealed()
        ) revert Unauthorized();
        if (IZZZVault(access.module(Ids.VAULT)).canonicalChainId() != block.chainid) revert UnsupportedTransport();
        if (_peer(sourceController).SCHEMA() != SCHEMA) revert UnsupportedTransport();
        incomingSource = sourceController;
        phase = PHASE_IMPORTING;
        access.canonicalTransition(STATE_IMPORTING, false, false);
        emit ImportPrepared(sourceController);
    }

function returnFunding(uint8 slot, uint256 index) external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_CANCELLED_IMPORT || source.phase() != PHASE_ABORTING
                || !incomingFunded[slot][index] || !source.returned(slot, index)
        ) revert Unauthorized();
        incomingFunded[slot][index] = false;
        _module(slot).canonicalRelease(index, source.moduleAt(slot));
    }

function returnFunds(uint8 slot, uint256 index) external nonReentrant {
        if (
            phase != PHASE_ABORTING || slot >= SLOTS || index >= assetCount[slot] || !funded[slot][index]
                || returned[slot][index]
        ) revert InvalidState();
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (peer.phase() != PHASE_CANCELLED_IMPORT) revert InvalidState();
        (address asset, uint256 amount) = _module(slot).canonicalBacking(index);
        returned[slot][index] = true;
        uint256 beforeBalance = _balance(asset, moduleAt(slot));
        peer.returnFunding(slot, index);
        if (_balance(asset, moduleAt(slot)) != beforeBalance + amount) revert InvalidBacking();
        _module(slot).canonicalRestore(index, peer.moduleAt(slot));
        emit BackingReturned(handoffId, slot, index);
    }

function settle(uint8 slot) external nonReentrant {
        if (phase != PHASE_SETTLING || slot != settlementCursor || slot >= SLOTS) revert InvalidState();
        access.canonicalTransition(STATE_FROZEN, true, false);
        _module(slot).canonicalSettle();
        access.canonicalTransition(STATE_FROZEN, false, false);
        settlementCursor = slot + 1;
        if (settlementCursor == SLOTS) phase = PHASE_EXPORTING;
        emit DomainSettled(handoffId, slot);
    }

function claimBatch(Claim[] calldata claims) external nonReentrant returns (uint256[] memory amounts) {
        uint256 length = claims.length;
        if (length == 0 || length > MAX_CLAIMS) revert InvalidBatch();
        if (!access.isSealed() || access.module(Ids.NFT) != nft) revert InvalidConfiguration();
        // Reject malformed/unauthorized batches before any payout callback.
        for (uint256 i; i < length; ++i) {
            Claim calldata entry = claims[i];
            if (IZZZNFT(nft).ownerOf(entry.nftId) != msg.sender) revert Unauthorized();
            for (uint256 j; j < i; ++j) {
                Claim calldata earlier = claims[j];
                if (entry.nftId == earlier.nftId && entry.asset == earlier.asset && entry.royalty == earlier.royalty) {
                    revert DuplicateClaim();
                }
            }
        }
        amounts = new uint256[](length);
        for (uint256 i; i < length; ++i) {
            Claim calldata entry = claims[i];
            // A preceding native/token callback may have transferred this NFT.
            // Each ledger independently repeats the same current-owner check.
            if (IZZZNFT(nft).ownerOf(entry.nftId) != msg.sender) revert Unauthorized();
            address target = entry.royalty ? royalties : access.module(Ids.REWARDS);
            if (target.code.length == 0) revert InvalidConfiguration();
            amounts[i] = IZZZClaimLedger(target).claimFor(entry.nftId, entry.asset, msg.sender);
        }
        emit BatchClaimed(msg.sender, length);
    }

function compound(uint256 id, uint128 minimumLiquidity, uint256 deadline) external onlyKeeper live operating {
        _deadline(deadline);
        if (minimumLiquidity == 0) revert InvalidAmount();
        IZZZVault(access.module(Ids.VAULT)).compound(id, minimumLiquidity, deadline);
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }

function begin(uint256 nft,uint256 bucket,uint256 packed,uint256 inputUSD,uint32 limits) external onlyBudget {
        _live();
        bytes32 pool = IZZZVault(access.module(Ids.VAULT)).group(bucket).poolId;
        if (basis.phase != 0) {
            if (!basis.entry || basis.phase != 1 || basis.pool != pool || basis.nft != nft ||
                basis.lowerInput != inputUSD || !IPricingEntry(_entry()).pricingContext(nft,pool,packed,inputUSD)) revert InvalidState();
        } else {
            basis.phase = 1; basis.nft = nft; _pair(pool);
            uint256 a0 = uint128(packed); uint256 a1 = packed >> 128;
            basis.lowerInput = _pairValue(a0,a1);
            basis.upperInput = _upper(basis.token0,a0) + _upper(basis.token1,a1);
            if (inputUSD != basis.lowerInput) revert InvalidAmount();
            _historicalMarks(bucket);
        }
        // A callback cannot adopt a later, wider governance/venue policy.
        // Even a tightening during this operation requires a fresh review.
        if (basis.limits != limits) revert InvalidState();
        basis.bucket = bucket;
        // Conversion/pull callbacks may not replace policies or round data.
        _unchanged();
    }

function beginEntryReviewed(uint256 nft,bytes32 pool,address source,uint256 amount,uint16 maximumLossBps,
        bytes32 expectedContributionPolicy)
        external returns(uint256 lowerUSD) {
        if (msg.sender != _entry()) revert Unauthorized();
        _live(); if (basis.phase != 0 || amount == 0) revert InvalidState();
        if (maximumLossBps > 1000) revert InvalidAmount();
        basis.phase = 1; basis.entry = true; basis.nft = nft;
        _pair(pool);
        if(expectedContributionPolicy==bytes32(0) || basis.entryPolicyFingerprint!=expectedContributionPolicy)revert InvalidState();
        if (uint16(basis.limits >> 16) > maximumLossBps) revert Slippage();
        _mark(source);
        Mark memory m = marks[source];
        lowerUSD = Math.mulDiv(amount,m.lower,m.scale);
        basis.lowerInput = lowerUSD;
        basis.upperInput = Math.mulDiv(amount,m.upper,m.scale,Math.Rounding.Ceil);
        _historicalMarks(IZZZVault(access.module(Ids.VAULT)).poolBucket(pool));
    }

function contributionNav(uint256 bucket) external onlyBudget returns(uint256 deployed,uint256 idle) {
        if (basis.phase == 0 || basis.phase > 3 || basis.bucket != bucket) revert InvalidState();
        if (basis.phase == 2) basis.putSpot = IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(basis.pool);
        if (basis.phase == 3) _putUnchanged();
        ++basis.phase;
        return nav(bucket);
    }

function endEntry() external {
        if (msg.sender != _entry()) revert Unauthorized();
        if (!basis.entry || basis.phase != 5) revert InvalidState();
        _putUnchanged(); _unchanged(); _clear();
    }

function finish(uint256 bucket,uint256 inputUSD,uint256 supply,uint256 incumbentNAV,
        uint256 incumbentDeployed,uint256 deployed,uint256 idle,uint32 limits)
        external onlyBudget returns(uint256 issued,uint256 netUSD) {
        if (basis.phase != 4 || basis.bucket != bucket || basis.lowerInput != inputUSD || basis.limits != limits ||
            uint16(limits) > 1000 || uint16(limits >> 16) > 1000) revert InvalidState();
        // Previously zero old-currency compound can first arrive during fee
        // synchronization. Mark it only for incumbent historical backing now;
        // never overwrite a starting mark or count it as newly deployed LP.
        _historicalMarks(bucket);
        _putUnchanged(); bytes32 hash = _unchanged();
        if (deployed == 0 || idle > Math.mulDiv(deployed+idle,basis.maxIdleBps,10000) ||
            deployed+idle <= incumbentNAV || deployed < incumbentDeployed) revert Slippage();
        netUSD = deployed+idle-incumbentNAV;
        uint256 required = basis.upperInput - Math.mulDiv(basis.upperInput,uint16(limits >> 16),10000);
        // Vault caps both balancing and deployment to the entrant's budget;
        // this baseline is the repriced incumbent physical LP only. Existing
        // idle/compound belongs in NAV, never in the marginal deployment test.
        if (netUSD < Math.mulDiv(basis.upperInput,10000-uint16(limits),10000) ||
            netUSD < required || deployed-incumbentDeployed < required) revert Slippage();
        issued = supply == 0 ? netUSD : Math.mulDiv(supply,netUSD,incumbentNAV+historicalValue(bucket));
        if (issued == 0 || supply+issued > 1e36) revert InvalidAmount();
        emit ContributionVerified(basis.nft,bucket,basis.lowerInput,basis.upperInput,
            deployed-incumbentDeployed,netUSD,basis.putSpot,hash);
        if (basis.entry) basis.phase = 5;
        else _clear();
    }

function allocate(uint256 id, address token, uint256 amount) external payable onlyModule(Ids.VAULT) nonReentrant canonicalAccounting {
        if (amount == 0) revert InvalidAmount();
        Position memory p = IZZZVault(msg.sender).group(id);
        if (p.status != PositionStatus.Active) revert InvalidState();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if (token != c.key.currency0 && token != c.key.currency1) revert InvalidConfiguration();
        _pull(token, amount);
        accounted[token] += amount;
        uint256 total = dust[id][token] + amount;
        // Twenty raw units allocate exactly 80/10/5/5. Smaller receipts carry
        // until another receipt or the incumbent-owner dust settlement barrier.
        uint256 units = total / 20;
        dust[id][token] = total % 20;
        if (units != 0) {
            compoundBalance[id][token] += units;
            buybackBalance[token] += units;
            accounted[token] -= units * 18;
            _credit(id, token, units * 16, units * 2);
        }
        _solvent(token);
        emit FeesAllocated(id, token, units * 20, dust[id][token]);
    }

function canonicalBarrier() external onlyCanonical nonReentrant {
        if (canonicalState() != 1) revert InvalidState();
    }

function canonicalSend(address asset, address destination, uint256 amount) external onlyCanonical nonReentrant {
        _push(asset, destination, amount);
    }

function canonicalWrite(uint8 kind, bytes calldata record) external onlyCanonical {
        if (canonicalState() != 2) revert InvalidState();
        if (kind == 0) {
            if (record.length != 160) revert InvalidState();
            (address asset, uint256 total, uint256 buyback,,) = abi.decode(record, (address,uint256,uint256,uint256,uint256));
            if (accounted[asset] != 0 || buybackBalance[asset] != 0 || buyback > total) revert InvalidState();
            accounted[asset] = total; buybackBalance[asset] = buyback;
        } else if (kind == 1) {
            if (record.length != 128) revert InvalidState();
            CanonicalBucket memory r = abi.decode(record, (CanonicalBucket));
            dust[r.id][r.asset] = r.dustAmount; compoundBalance[r.id][r.asset] = r.compoundAmount;
        } else revert InvalidState();
    }

function flushDust(uint256 id, address token) external nonReentrant canonicalAccounting {
        IZZZVault vault = _vault();
        if (!access.isSealed() || (msg.sender != address(vault) && msg.sender != access.module(Ids.MEMBERSHIP))) revert Unauthorized();
        Position memory p = vault.group(id);
        if (p.status != PositionStatus.Outbound && p.status != PositionStatus.Active && p.status != PositionStatus.Parked) revert InvalidState();
        _flushHomeDust(id, token);
    }

function releaseBuyback(address token, uint256 amount) external onlyModule(Ids.BUYBACK) nonReentrant canonicalAccounting {
        if (amount == 0 || amount > buybackBalance[token]) revert InvalidAmount();
        buybackBalance[token] -= amount;
        accounted[token] -= amount;
        _push(token, msg.sender, amount);
        _solvent(token);
    }

function releaseCompound(uint256 id, address token)
        external nonReentrant canonicalAccounting returns (uint256 amount) {
        if (!access.moduleAuthorized(Ids.VAULT, msg.sender)) revert Unauthorized();
        amount = compoundBalance[id][token];
        compoundBalance[id][token] = 0;
        accounted[token] -= amount;
        _push(token, msg.sender, amount);
        _solvent(token);
    }

function canonicalAccept(uint256 index, address) external payable onlyHandoff {
        if (access.canonicalState() != 2) revert InvalidState();
        _accept(index, false);
    }

function canonicalActivate() external onlyHandoff {
        if (access.canonicalState() != 2 || !imported || cursor != canonicalCount()) revert InvalidState();
    }

function canonicalCapture() external onlyHandoff {
        // Reject snapshotting from an ordinary allocation/reserve-send callback.
        fees.canonicalBarrier();
        imported = false;
        for (uint256 i; i < assets.length; ++i) delete accepted[i];
        delete assets; delete amounts; delete quarantine;
        groups = _vault().bucketCount();
        ICanonicalFeeAssets rewards = ICanonicalFeeAssets(access.module(Ids.REWARDS));
        lpAssets = rewards.assetCount();
        if (lpAssets == 0 || lpAssets > 33 || groups > 4) revert InvalidState();
        for (uint256 i; i < lpAssets; ++i) {
            address asset = rewards.assets(i);
            uint256 raw = _balance(asset, address(fees));
            assets.push(asset); amounts.push(0);
            // Donations remain quarantined, never converted into new income.
            // Restores are authenticated by the handoff's exact incoming delta;
            // arbitrary companion prefunds do not inflate the source snapshot.
            quarantine.push(raw - fees.accounted(asset));
            released[i] = false;
        }
        captured = true;
    }

function canonicalImport(uint256 row, bytes calldata record) external onlyHandoff {
        if (row != cursor++ || access.canonicalState() != 2) revert InvalidState();
        if (row == 0) {
            if (record.length != 64) revert InvalidState();
            (lpAssets, groups) = abi.decode(record, (uint256,uint256));
            if (lpAssets == 0 || lpAssets > 33 || groups > 4) revert InvalidState();
            imported = true; return;
        }
        --row;
        if (row < lpAssets) {
            if (record.length != 160) revert InvalidState();
            (address asset, uint256 total,, uint256 backing, uint256 q) =
                abi.decode(record, (address,uint256,uint256,uint256,uint256));
            if ((row == 0 ? asset != address(0) : asset == address(0) || asset.code.length == 0) || backing != total + q) revert InvalidState();
            for (uint256 i; i < row; ++i) if (assets[i] == asset) revert InvalidState();
            assets.push(asset); amounts.push(backing); quarantine.push(q);
            prefunds[asset] = _balance(asset, address(this));
            fees.canonicalWrite(0, record); return;
        }
        row -= lpAssets;
        if (row >= groups * lpAssets || record.length != 128) revert InvalidState();
        ZZZFeeController.CanonicalBucket memory r = abi.decode(record, (ZZZFeeController.CanonicalBucket));
        if (r.id != _vault().bucketAt(row / lpAssets) || r.asset != assets[row % lpAssets]) revert InvalidState();
        fees.canonicalWrite(1, record);
    }

function canonicalRelease(uint256 index, address destination) external onlyHandoff {
        uint8 state = access.canonicalState();
        if ((state != 1 && state != 4) || index >= assets.length || released[index] ||
            (state == 4 && !accepted[index])) revert InvalidState();
        released[index] = true;
        fees.canonicalSend(assets[index], destination, amounts[index]);
    }

function canonicalRestore(uint256 index, address) external payable onlyHandoff {
        if (access.canonicalState() != 1 || !released[index]) revert InvalidState();
        _accept(index, true); released[index] = false;
    }

function canonicalSettle() external onlyHandoff {
        if (!captured) revert InvalidState();
        for (uint256 i; i < groups; ++i) {
            uint256 id = _vault().bucketAt(i);
            for (uint256 j; j < lpAssets; ++j) fees.canonicalFlush(id, assets[j]);
        }
        for (uint256 i; i < lpAssets; ++i) {
            amounts[i] = fees.accounted(assets[i]) + quarantine[i];
            if (_balance(assets[i], address(fees)) < amounts[i]) revert InvalidState();
        }
    }

function configureExecutionPools(bytes32[] calldata pools, bytes32 reviewHash)
        external onlyGovernance operating principalOperating {
        if (pools.length > MAX_EXECUTION_POOLS || reviewHash == bytes32(0)) revert InvalidConfiguration();
        for (uint256 i; i < pools.length; ++i) {
            PoolConfig memory c = _pool(pools[i]);
            IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(pools[i]);
            (,,,uint24 fee) = stateView.getSlot0(pools[i]);
            if (fee != c.key.fee) revert InvalidConfiguration();
            for (uint256 j; j < i; ++j) if (pools[j] == pools[i]) revert InvalidConfiguration();
        }
        venues = pools;
        ++executionRevision;
        emit ExecutionPoolsConfigured(executionRevision, pools, reviewHash);
    }

function configureSolver(uint8 iterations, uint32 gasLimit, bytes32 reviewHash)
        external onlyGovernance operating principalOperating {
        if (iterations < 4 || iterations > 12 || gasLimit < 100000 || gasLimit > 300000 || reviewHash == bytes32(0))
            revert InvalidConfiguration();
        searchIterations = iterations; quoteGasLimit = gasLimit; ++executionRevision;
        emit SolverConfigured(executionRevision, iterations, gasLimit, reviewHash);
    }

function planReplacement(bytes32 target,int24 lower,int24 upper,uint256 amount0,uint256 amount1,uint16 mainFloor,uint256[4] calldata marks)
        external returns(Plan memory) {
        if(mainFloor<6000 || mainFloor>10000)revert InvalidConfiguration();
        return _plan(target,lower,upper,amount0,amount1,mainFloor,marks,true);
    }

function quoteCandidate(PoolKey calldata key, bool direction, uint256 amount) external returns (uint256 output,uint160 afterPrice,int24 afterTick) {
        if (msg.sender != address(this) || amount == 0 || amount > uint256(uint128(type(int128).max))) revert Unauthorized();
        bytes memory payload = abi.encode(key,direction,amount);
        pendingQuoteHash = keccak256(payload);
        try poolManager.unlock(payload) returns (bytes memory) { revert InvalidState(); }
        catch (bytes memory reason) {
            pendingQuoteHash = bytes32(0);
            bytes4 selector;
            if (reason.length == 100) assembly ("memory-safe") { selector := mload(add(reason,32)) }
            if (selector != QuoteResult.selector) revert InvalidState();
            int256 tickWord;
            assembly ("memory-safe") { output := mload(add(reason,36)) afterPrice := mload(add(reason,68)) tickWord := mload(add(reason,100)) }
            if (output == 0 || afterPrice == 0 || tickWord<TickMath.MIN_TICK || tickWord>=TickMath.MAX_TICK) revert InvalidState();
            afterTick=int24(tickWord);
        }
    }

function routePlan(ZZZLPBalanceMath.Context calldata x, bytes32 id, bool direction,bool requireActive) external returns (Plan memory best,uint256 bestValue) {
        if (msg.sender != address(this)) revert Unauthorized();
        PoolConfig memory c = _pool(id);
        PoolConfig memory target = _pool(x.target);
        if (c.key.currency1 != target.key.currency1) revert InvalidConfiguration();
        if(requireActive && id!=x.target && !_activeTarget(x))return(best,0);
        (uint160 beforePrice,,uint24 protocol,uint24 fee) = stateView.getSlot0(id);
        uint256 swapFee = _fee(c,direction,protocol,fee);
        if (!_validSpot(beforePrice,x.prices.referenceX96,c.maxSpotDeviationBps)) revert InvalidState();
        uint256 lo; uint256 hi = direction ? x.amount0 : x.amount1;
        if (hi > uint256(uint128(type(int128).max))) hi = uint256(uint128(type(int128).max));
        (uint256 input,uint256 initialResidual) = _seed(x,direction,swapFee);
        if (input == 0) return (best,0);
        if (input > hi) input = hi;
        best.revision = executionRevision;
        for (uint256 pass; pass < searchIterations && lo < hi; ++pass) {
            uint256 interpolated;
            bool quoted; uint256 output; uint160 afterPrice;int24 afterTick;
            try this.quoteCandidate{gas:quoteGasLimit}(c.key,direction,input) returns (uint256 out,uint160 price,int24 tick) {
                quoted = true; output = out; afterPrice = price;afterTick=tick;
            } catch {}
            if (!quoted) hi = input;
            else {
                int8 outside=requireActive && id==x.target?_tickSide(x.lower,x.upper,afterTick):int8(0);
                uint256 minimum = _minimum(x.prices,direction,input,
                    c.maxSlippageBps < target.maxSlippageBps ? c.maxSlippageBps : target.maxSlippageBps,swapFee);
                if (minimum == 0) lo = input+1;
                // Feasibility comes before the target-ratio bracket. Increasing
                // an already excessive trade cannot repair impact/spot limits.
                else if (output < minimum || !_validSpot(afterPrice,x.prices.referenceX96,c.maxSpotDeviationBps)) hi = input;
                else if(outside!=0) {
                    // Shrink an overshoot, but increase a trade which has not
                    // yet brought the destination into its required range.
                    if(direction ? outside<0 : outside>0)hi=input;
                    else lo=input+1;
                }
                else {
                    uint256 a0 = direction ? x.amount0-input : x.amount0+output;
                    uint256 a1 = direction ? x.amount1+output : x.amount1-input;
                    ZZZLPBalanceMath.Evaluation memory e = _evaluate(x,id == x.target ? afterPrice : x.spot,a0,a1);
                    // Keep one basis point of search headroom for rounded mint
                    // debts. A9999floor may be unavailable if full deployment
                    // cannot be represented; governance can choose a lower one.
                    bool meets=x.mainFloor<10000 && e.deployed>=Math.mulDiv(e.retained,x.mainFloor+1,10000,Math.Rounding.Ceil);
                    if(x.mainFloor<10000) {
                        if(meets) {
                            if(best.amountIn==0 || input<best.amountIn) {
                                bestValue=e.deployed;
                                best=Plan(id,direction,input,output,minimum,afterPrice,id==x.target?afterPrice:x.spot,
                                    executionRevision,policyFingerprint(x.target,id));
                            }
                            hi=input;
                        } else if(e.excess0==direction)lo=input+1;
                        else hi=input;
                    } else {
                        if(e.deployed>bestValue) {
                            bestValue=e.deployed;
                            best=Plan(id,direction,input,output,minimum,afterPrice,id==x.target?afterPrice:x.spot,
                                executionRevision,policyFingerprint(x.target,id));
                            if(e.deployed>=Math.mulDiv(e.retained,9990,10000))break;
                        }
                        if(e.excess0==direction)lo=input+1;
                        else hi=input;
                    }
                    // Safeguarded secant from the original zero-input residual:
                    // smooth v4 curves converge faster than midpoint-only
                    // search, without another real swap or an unbounded loop.
                    if (x.mainFloor==10000 && initialResidual != 0) {
                        if (e.excess0 == direction && e.imbalance < initialResidual) {
                            uint256 denominator = initialResidual-e.imbalance;
                            // Prove the quotient is bounded before mulDiv;
                            // a nearly flat residual must not overflow or jump
                            // outside the already established feasible bracket.
                            if (input < Math.mulDiv(hi,denominator,initialResidual))
                                interpolated = Math.mulDiv(input,initialResidual,denominator);
                        } else if (e.excess0 != direction && e.imbalance <= type(uint256).max-initialResidual) {
                            interpolated = Math.mulDiv(input,initialResidual,initialResidual+e.imbalance);
                        }
                    }
                }
            }
            if (lo >= hi) break;
            input = interpolated != 0 && interpolated >= lo && interpolated < hi ? interpolated : lo+(hi-lo)/2;
        }
    }

function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager) || pendingQuoteHash == bytes32(0) || keccak256(data) != pendingQuoteHash) revert Unauthorized();
        (PoolKey memory key,bool direction,uint256 amount) = abi.decode(data,(PoolKey,bool,uint256));
        int256 delta = poolManager.swap(key,IPoolManagerMinimal.SwapParams(direction,-int256(amount),
            direction ? TickMath.MIN_SQRT_PRICE+1 : TickMath.MAX_SQRT_PRICE-1),"");
        int128 d0 = int128(delta >> 128); int128 d1 = int128(uint128(uint256(delta)));
        int128 spent = direction ? d0 : d1; int128 received = direction ? d1 : d0;
        if (spent >= 0 || received <= 0 || uint256(-int256(spent)) != amount) revert Slippage();
        (uint160 afterPrice,int24 afterTick,,) = stateView.getSlot0(keccak256(abi.encode(key)));
        revert QuoteResult(uint256(int256(received)),afterPrice,afterTick);
    }

function close(bytes32 poolId, uint256 id, uint256 deadline) external onlyManager nonReentrant {
        _deadline(deadline);
        _main(id);
        PoolConfig memory c = _config(poolId, false);
        uint256 aux=secondaryId[id];
        _closeOne(poolId,c,id,deadline);
        if(aux!=0) {
            _closeOne(poolId,c,aux,deadline);
            delete secondaryId[id];delete primaryOfSecondary[aux];--activeSecondaryCount;
        }
    }

function closeSecondary(bytes32 poolId,uint256 main,uint256 deadline) external onlyManager nonReentrant {
        _deadline(deadline);
        if(!access.paused())revert InvalidState();
        _main(main);
        _checkPosition(poolId,main);
        uint256 aux=secondaryId[main];
        if(aux==0 || primaryOfSecondary[aux]!=main)revert InvalidState();
        _closeOne(poolId,_config(poolId,false),aux,deadline);
        delete secondaryId[main];delete primaryOfSecondary[aux];--activeSecondaryCount;
        if(!access.paused())revert InvalidState();
    }

function collect(bytes32 poolId, uint256 id, uint256 deadline) external onlyManager nonReentrant {
        _deadline(deadline);
        _main(id);
        PoolConfig memory c = _config(poolId, false);
        _collectOne(poolId,c.key,id,deadline);
        uint256 aux=secondaryId[id];
        if(aux!=0)_collectOne(poolId,c.key,aux,deadline);
    }

function increase(bytes32 poolId, uint256 id, uint256 amount0, uint256 amount1,
        uint128 minimumLiquidity, uint256 deadline)
        external payable onlyManager nonReentrant returns (uint256 spent0, uint256 spent1) {
        _main(id);
        (int24 lower, int24 upper) = _checkPosition(poolId, id);
        (, spent0, spent1) = _mintOrIncrease(poolId, id, lower, upper, amount0, amount1, minimumLiquidity, deadline);
    }

function mint(bytes32 poolId, int24 lower, int24 upper, uint256 amount0, uint256 amount1,
        uint128 minimumLiquidity, uint256 deadline)
        external payable onlyManager nonReentrant returns (uint256 tokenId, uint256 spent0, uint256 spent1) {
        return _mintOrIncrease(poolId, 0, lower, upper, amount0, amount1, minimumLiquidity, deadline);
    }

function addRoute(RoutePolicy calldata policy) external onlyGovernance operating nonReentrant returns (bytes32 id) {
        _checkRoute(policy);
        id = keccak256(abi.encode(policy));
        if (routeExists(id)) revert InvalidConfiguration();
        routes[id] = policy; v3RouteExists[id] = true; v3RouteEnabled[id] = true;
        emit RouteRecorded(id, policy.source, policy.reviewHash); emit RouteEnabled(id, true);
    }

function addV4Route(ZZZV4RouteExecutor.Policy calldata policy)
        external onlyGovernance operating nonReentrant returns (bytes32 id) {
        if (policy.source == address(0) || policy.output != address(0)) revert InvalidConfiguration();
        id = v4Executor.addRoute(policy);
        if (v3RouteExists[id]) revert InvalidConfiguration();
        emit V4RouteRecorded(id, policy.source, policy.reviewHash);
        emit RouteEnabled(id, true);
    }

function configureWrapper(WrapperPolicy calldata policy) external onlyGovernance operating nonReentrant {
        _checkWrapper(policy);
        wrapperPolicy = policy;
        emit WrapperConfigured(keccak256(abi.encode(policy)), policy.reviewHash);
    }

function convert(address source, uint256 amount, bytes32 routeId, uint256 minimumETH, uint256 deadline)
        external live operating nonReentrant returns (uint256 output) {
        if (msg.sender != ledger || !enabled) revert Unauthorized();
        _deadline(deadline);
        if (source == address(0) || amount == 0 || minimumETH == 0) revert InvalidAmount();
        if (routeKind(routeId) == 2) return _convertV4(source, amount, routeId, minimumETH, deadline);
        if (wrapper == address(0)) revert InvalidConfiguration();
        _checkWrapper(wrapperPolicy);
        RoutePolicy memory p;
        uint256 floor = amount;
        if (source == wrapper) {
            if (routeId != bytes32(0)) revert InvalidConfiguration();
        } else {
            if (!v3RouteEnabled[routeId]) revert InvalidConfiguration();
            p = routes[routeId];
            if (p.source != source) revert InvalidConfiguration();
            _checkRoute(p);
            uint256 expected = IZZZOracle(access.module(Ids.ORACLE)).quote(source, wrapper, amount);
            if (expected == 0) revert InvalidAmount();
            floor = Math.mulDiv(expected, 10_000 - conversionLossBps, 10_000, Math.Rounding.Ceil);
        }
        uint256 minimum = Math.max(floor, minimumETH);
        uint256 sourceBefore = IERC20(source).balanceOf(address(this));
        uint256 wrappedBefore = IERC20(wrapper).balanceOf(address(this));
        uint256 nativeBefore = address(this).balance;
        ExactToken.pull(source, ledger, amount);
        output = amount;
        if (source != wrapper) {
            IERC20(source).forceApprove(p.router, amount);
            output = IV3RouteRouter(p.router).exactInputSingle(IV3RouteRouter.ExactInputSingleParams(
                source, wrapper, p.fee, address(this), amount, minimum, 0));
            IERC20(source).forceApprove(p.router, 0);
            if (IERC20(source).balanceOf(address(this)) != sourceBefore ||
                IERC20(wrapper).balanceOf(address(this)) != wrappedBefore + output) revert InvalidState();
            _checkRoute(p);
        }
        if (output < minimum) revert Slippage();
        nativeSender = wrapper;
        IRewardWrapper(wrapper).withdraw(output);
        nativeSender = address(0);
        _checkWrapper(wrapperPolicy);
        if (IERC20(wrapper).balanceOf(address(this)) != wrappedBefore ||
            address(this).balance != nativeBefore + output) revert InvalidState();
        (bool ok,) = payable(ledger).call{value: output}("");
        if (!ok || address(this).balance != nativeBefore) revert InvalidState();
        emit Converted(source, routeId, amount, output);
    }

function setConversionLossBps(uint16 value) external onlyGovernance operating nonReentrant {
        if (value > MAX_LOSS_BPS) revert InvalidConfiguration();
        uint16 previous = conversionLossBps;
        conversionLossBps = value;
        emit ConversionLossLimitChanged(previous, value);
    }

function setEnabled(bool value) external onlyGovernance operating nonReentrant {
        enabled = value; emit Enabled(value);
    }

function setRouteEnabled(bytes32 id, bool value) external onlyGovernance operating nonReentrant {
        uint8 kind = routeKind(id);
        if (kind == 0) revert InvalidConfiguration();
        if (kind == 1) {
            if (value) _checkRoute(routes[id]);
            v3RouteEnabled[id] = value;
        } else v4Executor.setRouteEnabled(id, value);
        emit RouteEnabled(id, value);
    }

function balance(bytes32 targetPool,uint256 existingLpId,uint256 amount0,uint256 amount1,uint256 deadline)
        external payable onlyModule(Ids.VAULT) nonReentrant returns (uint256 balanced0,uint256 balanced1) {
        _deadline(deadline);
        if (amount0 > type(uint128).max || amount1 > type(uint128).max || msg.value != amount0) revert InvalidAmount();
        PoolConfig memory target = _config(targetPool,true);
        // _config already requires native currency0, including in emergencies.
        bytes32 context = _balanceContext(targetPool);
        uint256 nativePrefund = address(this).balance-msg.value;
        uint256 tokenPrefund = IERC20(target.key.currency1).balanceOf(address(this));
        bool emergency = _emergencyBudget() != address(0);
        EmergencyRebalance memory request;
        if(emergency) request = IZZZEmergencyController(access.module(Ids.MIGRATION)).emergencyRequest();
        int24 lower; int24 upper; uint128 priorLiquidity;
        if (existingLpId != 0) {
            (lower,upper) = _checkPosition(targetPool,existingLpId);
            priorLiquidity = posm.getPositionLiquidity(existingLpId);
        } else if(emergency) {
            lower = request.lower; upper = request.upper;
        } else (lower,upper,) = IZZZStrategy(access.module(Ids.STRATEGY)).target(targetPool);
        // Pull before quoting: even a token callback cannot intervene between
        // the simulated route and the actual swap. Refund only this budget.
        ExactToken.pull(target.key.currency1,msg.sender,amount1);
        if (_balanceContext(targetPool) != context) revert InvalidState();
        ZZZLPBalancer.Plan memory p;
        if(emergency) {
            p.poolId = request.swapPool; p.zeroForOne = request.zeroForOne;
            p.amountIn = request.amountIn; p.minimumOut = request.minimumOut;
        } else if(existingLpId==0 && _ordinaryReplacement()) {
            // The router adds sizing headroom only when a trade is needed.
            // Actual final allocation retains the captured governed floor.
            uint256[4] memory marks;
            (marks[0],marks[1],marks[2],marks[3])=
                IPortfolioBudget(IPortfolioVault(access.module(Ids.VAULT)).migrationBudget()).maintenancePrices();
            p=balancingRouter.planReplacement(targetPool,lower,upper,amount0,amount1,
                _portfolioPolicy().enabled(targetPool)?_portfolioPolicy().minimumMainBps(targetPool):10000,marks);
        } else p = balancingRouter.plan(targetPool,lower,upper,amount0,amount1);
        balanced0 = amount0; balanced1 = amount1;
        uint256 refund0 = amount0; uint256 refund1 = amount1;
        if (p.amountIn != 0) {
            PoolConfig memory venue = _config(p.poolId,true);
            if (venue.key.currency1 != target.key.currency1 ||
                p.amountIn > (p.zeroForOne ? amount0 : amount1)) revert InvalidState();
            uint256 output = _swapExact(p.poolId,venue,p.zeroForOne,p.amountIn,p.minimumOut,msg.sender);
            if (!emergency && (output != p.amountOut || spot(p.poolId) != p.sqrtAfter)) revert Slippage();
            if (p.zeroForOne) { balanced0 -= p.amountIn; balanced1 += output; refund0 -= p.amountIn; }
            else { balanced1 -= p.amountIn; balanced0 += output; refund1 -= p.amountIn; }
        }
        _sendNative(msg.sender,refund0);
        ExactToken.push(target.key.currency1,msg.sender,refund1);
        if (existingLpId != 0) {
            (int24 finalLower,int24 finalUpper) = _checkPosition(targetPool,existingLpId);
            if (lower != finalLower || upper != finalUpper || posm.getPositionLiquidity(existingLpId) != priorLiquidity) revert InvalidState();
        }
        if (address(this).balance != nativePrefund || IERC20(target.key.currency1).balanceOf(address(this)) != tokenPrefund ||
            _balanceContext(targetPool) != context) revert InvalidState();
        if(!emergency && (balancingRouter.executionRevision() != p.revision ||
            balancingRouter.policyFingerprint(targetPool,p.poolId) != p.fingerprint ||
            _policySpot(targetPool) != p.targetSqrtAfter)) revert InvalidState();
        if(emergency) _policySpot(targetPool);
    }

